const { withDangerousMod } = require('@expo/config-plugins');
const fs = require('fs');
const path = require('path');

/**
 * Copies apps/travel-host/xcode.env.updates → ios/.xcode.env.updates on prebuild
 * so Xcode release builds use Re.Pack instead of Expo Metro (export:embed).
 */
function withRepackXcodeBundle(config) {
  return withDangerousMod(config, [
    'ios',
    async config => {
      const projectRoot = config.modRequest.projectRoot;
      const sourcePath = path.join(projectRoot, 'xcode.env.updates');
      const targetPath = path.join(
        config.modRequest.platformProjectRoot,
        '.xcode.env.updates'
      );

      const raw = await fs.promises.readFile(sourcePath, 'utf8');
      const body = raw
        .split('\n')
        .filter(line => !line.startsWith('#'))
        .join('\n')
        .trim();

      const header =
        '# Generated by withRepackXcodeBundle — edit xcode.env.updates at project root.\n';
      await fs.promises.writeFile(targetPath, `${header}${body}\n`);

      return config;
    },
  ]);
}

module.exports = withRepackXcodeBundle;
